"Теперь ты знаешь устройства компьютера!": "Maintenant tu connais les appareils de l'ordinateur !",
"Помни эти правила, когда садишься за компьютер!": "Souviens-toi de ces règles quand tu t'assieds devant l'ordinateur !",
"Правило": "Règle",
"Все порядки действий собраны верно!": "Tous les ordres d'actions sont corrects !",
"Верно! Теперь следующее задание.": "Exact ! Passons à l'exercice suivant.",
"Видео: Устройства компьютера": "Vidéo : les appareils de l'ordinateur",
"Посмотри видео от Барсика. Когда досмотришь, нажми «Дальше» — и тебя ждут задания.": "Regarde la vidéo de Barsik. Quand tu as fini, appuie sur « Suivant » : les exercices t'attendent.",
"Знакомимся с устройствами": "Faisons connaissance avec les appareils",
"Привет! Это Барсик. Сегодня мы познакомимся с компьютером. У компьютера есть разные устройства. Монитор, клавиатура, мышь, принтер, колонки, ноутбук, наушники и джойстик. Нажимай на каждое и узнавай, для чего оно нужно.": "Salut ! C'est Barsik. Aujourd'hui, nous allons découvrir l'ordinateur. Il a différents appareils : écran, clavier, souris, imprimante, haut-parleurs, ordinateur portable, casque et manette. Clique sur chacun et découvre à quoi il sert.",
"Как называется устройство?": "Comment s'appelle cet appareil ?",
"Посмотри на картинку и выбери название устройства.": "Regarde l'image et choisis le nom de l'appareil.",
"Найди устройство": "Trouve l'appareil",
"Теперь наоборот. Прочитай название и найди нужную картинку.": "Maintenant, à l'envers. Lis le nom et trouve la bonne image.",
"Видео: Что делает устройство?": "Vidéo : que fait l'appareil ?",
"Угадай устройство": "Devine l'appareil",
"Я опишу устройство, а ты угадаешь, что это. Читай внимательно.": "Je décris un appareil et tu devines lequel c'est. Lis bien.",
"Управляем или смотрим?": "On commande ou on regarde ?",
"Одними устройствами мы управляем: это клавиатура, мышь и джойстик. Другие показывают, печатают или звучат: монитор, принтер, колонки и наушники. Реши, к какой группе относится устройство.": "Avec certains appareils, on commande : le clavier, la souris et la manette. D'autres affichent, impriment ou émettent du son : l'écran, l'imprimante, les haut-parleurs et le casque. Décide à quel groupe appartient l'appareil.",
"Проверим себя": "Vérifions-nous",
"Повторим всё вместе: названия, описания и группы устройств.": "Révisons tout ensemble : les noms, les descriptions et les groupes des appareils.",
"Видео: Правила работы": "Vidéo : les règles de travail",
"Правила за компьютером": "Les règles devant l'ordinateur",
"За компьютером нужно вести себя правильно. Сиди прямо и не слишком близко к экрану. Делай перерывы, когда устали глаза. Не трогай розетки и провода. Никому не говори свой пароль. А если что-то напугало, позови взрослого. Нажимай на карточки и читай.": "Il faut bien se tenir devant l'ordinateur. Assieds-toi droit, pas trop près de l'écran. Fais une pause quand tes yeux sont fatigués. Ne touche pas aux prises ni aux fils. Ne dis ton mot de passe à personne. Et si quelque chose te fait peur, appelle un adulte. Clique sur les cartes et lis.",
"Правильно или нет?": "Juste ou pas ?",
"Прочитай правило и скажи, правильно ли так делать.": "Lis la règle et dis s'il est juste d'agir ainsi.",
"Проверим правила": "Vérifions les règles",
"Ещё раз проверим правила и устройства.": "Vérifions encore une fois les règles et les appareils.",
"Видео: Порядок действий": "Vidéo : l'ordre des actions",
"Расставь шаги по порядку": "Range les étapes dans l'ordre",
"Компьютер умеет выполнять действия только по порядку, шаг за шагом. Такой порядок действий называют алгоритмом. Попробуй сам. Нажимай на шаги по порядку: что делаем сначала, что потом.": "L'ordinateur ne sait exécuter des actions que dans l'ordre, pas à pas. Cet ordre d'actions s'appelle un algorithme. Essaie toi-même. Clique sur les étapes dans l'ordre : que fait-on d'abord, puis ensuite ?",
"Что делаем раньше?": "Que fait-on en premier ?",
"Ответь, что нужно сделать первым, последним, а что сразу после этого шага.": "Réponds : que faut-il faire en premier, en dernier, et juste après cette étape ?",
"Смешанные задания": "Exercices variés",
"Последняя проверка курса. Устройства, правила и порядок действий.": "Dernière vérification du cours. Les appareils, les règles et l'ordre des actions.",
"Курс пройден!": "Cours terminé !",
"Теперь ты знаешь устройства компьютера, правила безопасной работы и умеешь расставлять шаги по порядку. Дальше тренируйся в играх. Я буду рядом!": "Maintenant tu connais les appareils de l'ordinateur, les règles de travail en sécurité, et tu sais ranger les étapes dans l'ordre. Continue de t'entraîner dans les jeux. Je serai là !",
