"Корень держит растение в земле и берёт из земли воду.": "La racine maintient la plante dans la terre et y puise l'eau.",
"Стебель": "Tige",
"Стебель держит листья и цветки. По нему вода идёт вверх.": "La tige porte les feuilles et les fleurs. L'eau y monte.",
"Лист": "Feuille",
"Листья дышат и помогают растению расти на свету.": "Les feuilles respirent et aident la plante à grandir à la lumière.",
"Цветок": "Fleur",
"Цветок — самая красивая часть. Из цветка потом появляется плод.": "La fleur est la plus belle partie. Plus tard, le fruit apparaît à partir de la fleur.",
"Плод": "Fruit",
"В плоде спрятаны семена.": "Les graines sont cachées dans le fruit.",
"Семя": "Graine",
"Из семени вырастает новое растение.": "De la graine pousse une nouvelle plante.",
"Без воды растение вянет.": "Sans eau, la plante se flétrit.",
"Свет нужен листьям, чтобы растение росло.": "Les feuilles ont besoin de lumière pour que la plante grandisse.",
"Тепло": "Chaleur",
"В тепле растение растёт, а на морозе замерзает.": "Au chaud, la plante pousse ; dans le gel, elle gèle.",
"Конфета": "Bonbon",
"Кроссовки": "Baskets",
"Земля сухая, листья висят и вянут.": "La terre est sèche, les feuilles pendent et se flétrissent.",
"Растение стоит в тёмном шкафу, стебель бледный и тонкий.": "La plante est dans une armoire sombre, la tige est pâle et fine.",
"На улице мороз, растение замёрзло.": "Il gèle dehors, la plante est gelée.",
