"Улетает в тёплые края": "S'envole vers les pays chauds",
"Птицы улетают в тёплые края, где зимой есть корм.": "Les oiseaux s'envolent vers les pays chauds, où il y a de la nourriture en hiver.",
"Делает запасы": "Fait des réserves",
"Эти животные осенью собирают корм и прячут его на зиму.": "Ces animaux ramassent de la nourriture en automne et la cachent pour l'hiver.",
"Спит всю зиму": "Dort tout l'hiver",
"Эти животные зимой засыпают в своём убежище и спят до весны.": "Ces animaux s'endorment l'hiver dans leur abri et dorment jusqu'au printemps.",
