"Без света росток слабеет: растениям нужен свет.": "Sans lumière, la pousse s'affaiblit : les plantes ont besoin de lumière.",
"Лёд и тепло": "La glace et la chaleur",
"Два кубика льда. Один положили на тёплое блюдце на солнце, другой оставили в морозилке.": "Deux glaçons. L'un est posé sur une soucoupe chaude au soleil, l'autre est resté au congélateur.",
"На солнце": "Au soleil",
"В морозилке": "Au congélateur",
