"Выбери, зачем нужно знать то, о чём спрашивает вопрос.": "Choisis pourquoi il faut savoir ce que demande la question.",
"Дневник погоды": "Journal météo",
"Ты будешь настоящим исследователем. Четыре дня подряд смотри в окно и на термометр и записывай в дневник погоду и температуру.": "Tu vas être un vrai chercheur. Pendant quatre jours, regarde par la fenêtre et le thermomètre et note le temps et la température dans ton journal.",
"Как наблюдать": "Comment observer",
"Вспомни, как правильно проводить наблюдения.": "Rappelle-toi comment bien faire des observations.",
"Видео: Опыты и сравнения": "Vidéo : expériences et comparaisons",
"Смотрим опыты": "Regardons les expériences",
"Сейчас ты увидишь три опыта. Сначала посмотри, что мы приготовили. Потом нажми «Запустить опыт», увидь результат и объясни, почему так получилось.": "Maintenant tu vas voir trois expériences. Regarde d'abord ce que nous avons préparé. Puis clique sur « Lancer l'expérience », vois le résultat et explique pourquoi c'est arrivé.",
"Что получится?": "Que va-t-il se passer ?",
"Подумай, что получится в опыте, и выбери ответ.": "Réfléchis à ce qui va se passer dans l'expérience et choisis la réponse.",
"Животные и растения": "Animaux et plantes",
"Давай сравним животных и растения. Выбери, у кого есть этот признак: только у животных, только у растений или у обоих.": "Comparons les animaux et les plantes. Choisis qui a cette caractéristique : seulement les animaux, seulement les plantes ou les deux.",
"Сходства и различия": "Ressemblances et différences",
"Ответь на вопросы о том, чем похожи и чем отличаются животные и растения.": "Réponds aux questions sur ce qui rapproche et ce qui distingue les animaux et les plantes.",
"Последняя проверка: зачем изучать природу, наблюдения, опыты и сравнения.": "Dernière vérification : pourquoi étudier la nature, observations, expériences et comparaisons.",
"Теперь ты знаешь, зачем изучать природу, как проводить наблюдения, как объяснять опыты и сравнивать животных и растения. Дальше тренируйся в играх. Я буду рядом!": "Maintenant tu sais pourquoi étudier la nature, comment observer, expliquer des expériences et comparer les animaux et les plantes. Continue de t'entraîner dans les jeux. Je serai là !",
