"круглое, как Земля.": "est rond comme la Terre.",
"не круглое, а Земля круглая.": "n'est pas rond, mais la Terre est ronde.",
"Изучать космос": "Étudier l'espace",
"Измерять время": "Mesurer le temps",
"Естественный свет даёт природа, искусственный — человек.": "La lumière naturelle vient de la nature, l'artificielle de l'homme.",
"Естественный источник света: его создала природа.": "Source de lumière naturelle : la nature l'a créée.",
"Искусственный источник света: его сделал человек.": "Source de lumière artificielle : l'homme l'a fabriquée.",
"Костёр, свеча и Солнце греют, а снег и лёд холодные.": "Le feu de camp, la bougie et le Soleil chauffent, la neige et la glace sont froides.",
"Это тёплое: оно греет, рядом с ним тепло.": "C'est chaud : cela chauffe, il fait chaud à côté.",
"Звуки есть в природе и есть звуки, которые делает человек.": "Il y a des sons dans la nature et des sons faits par l'homme.",
"Естественный источник звука: звук идёт от природы или животного.": "Source sonore naturelle : le son vient de la nature ou d'un animal.",
"Искусственный источник звука: его сделал человек.": "Source sonore artificielle : l'homme l'a fabriquée.",
"Помни: розетки и провода трогать нельзя!": "Souviens-toi : il ne faut pas toucher les prises et les fils !",
"Работает от электричества. Но розетки и провода трогать нельзя — это опасно!": "Fonctionne à l'électricité. Mais il ne faut pas toucher les prises et les fils : c'est dangereux !",
"Это не работает от электричества.": "Cela ne fonctionne pas à l'électricité.",
"Земля круглая, как мяч. Глобус — её модель.": "La Terre est ronde comme un ballon. Le globe en est le modèle.",
"Глобус — это модель Земли. Земля круглая, как шар.": "Le globe est un modèle de la Terre. La Terre est ronde comme une boule.",
"Круглое, как Земля.": "Rond comme la Terre.",
"Это не круглое, не похоже на Землю.": "Ce n'est pas rond, cela ne ressemble pas à la Terre.",
"Космос изучают приборами, а время измеряют часами и календарём.": "On étudie l'espace avec des instruments, et on mesure le temps avec une horloge et un calendrier.",
"Этот прибор — для космоса.": "Cet instrument sert à l'espace.",
"Этот прибор — для времени.": "Cet instrument sert au temps.",
"Магнит притянул! Он сделан из железа.": "L'aimant l'a attiré ! C'est fait de fer.",
