"На пейзаже нарисована природа: поле, горы, деревья, небо.": "Sur le paysage, on a dessiné la nature : un champ, des montagnes, des arbres, le ciel.",
"На портрете нарисован человек, его лицо.": "Sur le portrait, on a dessiné une personne, son visage.",
"На натюрморте нарисованы предметы: фрукты, посуда, цветы.": "Sur la nature morte, on a dessiné des objets : des fruits, de la vaisselle, des fleurs.",
