"Шарик: скатай кусочек пластилина между ладонями круговыми движениями.": "La boule : roule un petit morceau de pâte entre les paumes avec des mouvements circulaires.",
"раскатать ладонями вперёд и назад": "rouler avec les paumes d'avant en arrière",
"Колбаска: раскатай пластилин ладонями вперёд и назад.": "Le boudin : roule la pâte avec les paumes d'avant en arrière.",
"Лепёшка": "Galette",
"сплющить шарик ладонью": "aplatir la boule avec la paume",
"Лепёшка: сплющи шарик ладонью или пальцем.": "La galette : aplatis la boule avec la paume ou le doigt.",
