"Вырезать детали из цветной бумаги": "Découper les pièces dans du papier de couleur",
"Разложить детали на листе": "Disposer les pièces sur la feuille",
"Приклеить": "Coller",
"Скатать три шарика": "Rouler trois petites boules",
"Соединить шарики": "Assembler les boules",
"Вылепить нос-морковку": "Modeler le nez en carotte",
"Сделать глаза": "Faire les yeux",
"Пластилин можно попробовать на вкус": "On peut goûter la pâte à modeler",
"Пластилин нельзя брать в рот, он несъедобный.": "On ne doit pas mettre la pâte à modeler dans la bouche : ce n'est pas comestible.",
"Руки после пластилина обязательно моют.": "Après la pâte à modeler, on se lave toujours les mains.",
"Лепить лучше на подложке": "Il vaut mieux modeler sur un support",
"Подложка защищает стол от пятен.": "Le support protège la table des taches.",
"Пластилином можно пачкать мебель": "On peut salir les meubles avec la pâte à modeler",
"Мебель нужно беречь, лепи только на подложке.": "Il faut prendre soin des meubles : modèle seulement sur le support.",
"Из пластилина можно слепить фигурку": "On peut modeler une figurine avec de la pâte",
"Из пластилина лепят фигурки.": "On modèle des figurines avec la pâte à modeler.",
"Так передавать безопасно.": "Les passer ainsi est sans danger.",
"С ножницами нельзя бегать, можно пораниться.": "On ne doit pas courir avec des ciseaux : on peut se blesser.",
"Когда работа закончена, ножницы кладут на место": "Quand le travail est fini, on range les ciseaux à leur place",
"Инструменты после работы убирают.": "Après le travail, on range les outils.",
"Клей нельзя пробовать, он несъедобный.": "On ne doit pas goûter la colle : ce n'est pas comestible.",
"Кисточку после работы нужно вымыть": "Après le travail, il faut laver le pinceau",
"Кисть моют в воде, чтобы она не засохла.": "On lave le pinceau dans l'eau pour qu'il ne sèche pas.",
"На выставке работы смотрят глазами и не трогают руками": "À l'exposition, on regarde les œuvres avec les yeux et on ne les touche pas",
"Работы можно испортить, поэтому трогать их нельзя.": "On peut abîmer les œuvres, donc il ne faut pas les toucher.",
"Можно смеяться над чужим рисунком": "On peut se moquer du dessin d'un autre",
"Над чужой работой смеяться нельзя, это обидно.": "On ne doit pas se moquer du travail des autres, cela fait de la peine.",
"Другу можно сказать доброе слово о его рисунке": "On peut dire un mot gentil à un ami sur son dessin",
"Доброе слово радует автора.": "Un mot gentil fait plaisir à l'auteur.",
"Свою работу можно подписать названием": "On peut donner un titre à son œuvre",
"У каждой работы есть название.": "Chaque œuvre a un titre.",
"Можно рассказать, чем ты рисовал и что хотел показать": "On peut dire avec quoi on a dessiné et ce qu'on voulait montrer",
"Рассказ помогает зрителям понять работу.": "Le récit aide les spectateurs à comprendre l'œuvre.",
"дают": "donnent",
"Основные цвета: красный, жёлтый и синий. Остальные получаются, когда их смешивают.": "Les couleurs primaires : rouge, jaune et bleu. Les autres s'obtiennent en les mélangeant.",
"Правильный цвет:": "La bonne couleur :",
"Тёплый": "Chaude",
"Холодный": "Froide",
"Тёплые цвета как солнце и огонь: красный, оранжевый, жёлтый. Холодные как лёд и вода: синий, голубой, фиолетовый.": "Les couleurs chaudes sont comme le soleil et le feu : rouge, orange, jaune. Les froides sont comme la glace et l'eau : bleu, bleu clair, violet.",
"Тёплыми": "Chaudes",
"Холодными": "Froides",
"Тёплые цвета рассказывают о радости и жаре, холодные о тишине и холоде.": "Les couleurs chaudes parlent de joie et de chaleur, les froides de silence et de froid.",
