"Искусство нашей страны": "L'art de notre pays",
"Ковры": "Tapis",
"Войлочные ковры": "Tapis de feutre",
"Казахские мастерицы делают из войлока красивые ковры с узорами: кошму и сырмак. Тұскиіз — расшитый ковёр на стену юрты.": "Les artisanes kazakhes font avec le feutre de beaux tapis à motifs : le feutre et le сырмақ. Le тұскиіз est un tapis brodé que l'on accroche au mur de la yourte.",
"Юрта — это дом кочевников. Она круглая, лёгкая и красиво украшена узорами.": "La yourte est la maison des nomades. Elle est ronde, légère et joliment décorée de motifs.",
"Домбра и кюй": "Dombra et küi",
"Домбра — казахский музыкальный инструмент. Кюй — музыка, в которой композитор рассказывает о природе и чувствах.": "La dombra est un instrument de musique kazakh. Le küi est une musique par laquelle le compositeur parle de la nature et des sentiments.",
"Мир": "Le monde",
"Искусство мира": "L'art du monde",
"У каждого народа свои картины, скульптуры, здания и узоры. Все они рассказывают о людях и их чувствах.": "Chaque peuple a ses tableaux, ses sculptures, ses bâtiments et ses motifs. Tous parlent des gens et de leurs sentiments.",
"Искусство рассказывает о чувствах. В Казахстане его создают веками: войлочные ковры, юрты, музыка домбры. И у других народов мира тоже много красивых произведений. Нажимай на картинки и знакомься.": "L'art parle de sentiments. Au Kazakhstan, on le crée depuis des siècles : tapis de feutre, yourtes, musique de la dombra. Les autres peuples du monde ont aussi beaucoup de belles œuvres. Clique sur les images et fais connaissance.",
"Что мы знаем об искусстве": "Ce que nous savons de l'art",
"Ответь на вопросы про искусство нашей страны и про то, что такое произведение искусства.": "Réponds aux questions sur l'art de notre pays et sur ce qu'est une œuvre d'art.",
"Какое настроение?": "Quelle ambiance ?",
"Посмотри на картинку и скажи, какое настроение она передаёт. Помогут цвета: тёплые и яркие радуют, тёмные и холодные грустят или тревожат.": "Regarde l'image et dis quelle ambiance elle exprime. Les couleurs t'aideront : les couleurs chaudes et vives apportent de la joie, les sombres et froides de la tristesse ou de l'inquiétude.",
"Видео: Графика: приёмы": "Vidéo : techniques du dessin",
"Приёмы графики": "Techniques du dessin",
"В графике много приёмов: линия, штриховка и точки. Вспомни, для чего они нужны.": "Dans le dessin, il y a beaucoup de techniques : la ligne, les hachures et les points. Rappelle-toi à quoi elles servent.",
"Рисуем разными приёмами": "Dessinons avec différentes techniques",
"Нарисуй линию карандашом": "Dessine une ligne au crayon",
"Выбери «Карандаш» и проведи пальцем или мышкой по листу.": "Choisis « Crayon » et passe le doigt ou la souris sur la feuille.",
"Нарисуй фигуру фломастером и заштрихуй её": "Dessine une figure au feutre et hachure-la",
"Сначала «Фломастер», потом «Штриховка».": "D'abord « Feutre », puis « Hachures ».",
"Сделай точками небо или землю": "Fais le ciel ou la terre avec des points",
"Выбери «Точки» и веди по листу.": "Choisis « Points » et déplace-toi sur la feuille.",
"Нарисуй дерево, дом или животное тремя разными приёмами": "Dessine un arbre, une maison ou un animal avec trois techniques différentes",
"Попробуй разные инструменты и цвета: художники всегда экспериментируют.": "Essaie différents outils et couleurs : les artistes expérimentent toujours.",
"Теперь порисуем разными приёмами. Выполняй задания по порядку. Пробуй карандаш, фломастер, штриховку и точки. Ты можешь стереть всё и начать заново.": "Maintenant, dessinons avec différentes techniques. Fais les tâches dans l'ordre. Essaie le crayon, le feutre, les hachures et les points. Tu peux tout effacer et recommencer.",
