"Видео: Что такое сложение?": "Vidéo : qu'est-ce que l'addition ?",
"Объединяем яблоки": "Réunissons les pommes",
"Собираем числа": "Rassemblons les nombres",
"Теперь решаешь ты! Нажимай «плюс» и «минус», чтобы собрать нужное число. Красные кружки — первое число, жёлтые — второе. Все вместе они заполняют рамку.": "Maintenant, c'est toi qui résous ! Clique sur « plus » et « moins » pour former le nombre voulu. Les ronds rouges sont le premier nombre, les jaunes le second. Ensemble, ils remplissent le cadre.",
"Как называются числа": "Comment s'appellent les nombres",
"Сколько всего?": "Combien en tout ?",
"Проверим! Сосчитай все яблоки вместе и выбери ответ. Если ошибёшься — я подскажу.": "Vérifions ! Compte toutes les pommes ensemble et choisis la réponse. Si tu te trompes, je te donnerai un indice.",
"Примеры и названия": "Exemples et noms",
"Последняя проверка урока: примеры на сложение и названия чисел.": "Dernière vérification de la leçon : exemples d'addition et noms des nombres.",
"Видео: Сложение на числовом луче": "Vidéo : l'addition sur la droite numérique",
"Заяц прыгает по лучу": "Le lièvre saute sur la droite",
"Числовой луч — это линия, на которой числа стоят по порядку. Прибавить — значит прыгнуть вправо. Выбери, где стоит заяц и сколько прыжков сделать, и нажми «Прыгай»!": "La droite numérique est une ligne où les nombres se suivent dans l'ordre. Ajouter, c'est sauter vers la droite. Choisis où se tient le lièvre et combien de sauts faire, puis clique sur « Saute ! ».",
"Куда он приземлится?": "Où va-t-il atterrir ?",
"Теперь попробуй угадать! Я скажу, где стоит заяц и сколько прыжков он сделает. Нажми на число, где он окажется.": "Maintenant, essaie de deviner ! Je te dis où se tient le lièvre et combien de sauts il fait. Clique sur le nombre où il arrivera.",
"Хитрость: досчитываем": "Astuce : on continue de compter",
"Есть хитрость, как складывать быстрее. Начни с большего числа и досчитай меньшее по одному шагу. Нажми «Досчитать» и смотри!": "Il y a une astuce pour additionner plus vite. Commence par le plus grand nombre et ajoute le plus petit pas à pas. Clique sur « Continue de compter » et regarde !",
"Проверяем себя": "Vérifions-nous",
"Проверим, как ты прыгаешь по лучу! Отвечай на вопросы.": "Voyons comment tu sautes sur la droite ! Réponds aux questions.",
"Видео: Состав числа": "Vidéo : la composition d'un nombre",
"Домик числа": "La maison du nombre",
"Все способы": "Toutes les façons",
"Посмотри, как выглядят все способы разложить число на две части. Выбери число сверху.": "Regarde toutes les façons de décomposer un nombre en deux parties. Choisis le nombre en haut.",
"Сколько не хватает?": "Combien en manque-t-il ?",
"Всего кружков столько, сколько написано. Часть уже закрашена. Сколько ещё нужно?": "Il y a autant de ronds au total que le nombre écrit. Une partie est déjà coloriée. Combien en faut-il encore ?",
"Найди лишнее": "Trouve l'intrus",
"Последние задания урока. Смотри внимательно: одно из равенств может быть неверным!": "Derniers exercices de la leçon. Regarde bien : l'une des égalités peut être fausse !",
"Видео: Свойства сложения": "Vidéo : les propriétés de l'addition",
"От перемены мест…": "En changeant l'ordre…",
"Что будет, если поменять слагаемые местами? Нажми на кнопку и посмотри, как изменится сумма.": "Que se passe-t-il si on échange les termes ? Clique sur le bouton et regarde comment la somme change.",
"Плюс ноль и плюс один": "Plus zéro et plus un",
"Есть два особых случая. Что будет, если прибавить ноль? А если прибавить один? Переключай вкладки!": "Il y a deux cas particuliers. Que se passe-t-il si on ajoute zéro ? Et si on ajoute un ? Change d'onglet !",
"Меняем местами": "Échangeons",
"Используй правило: от перемены мест слагаемых сумма не меняется.": "Utilise la règle : quand on échange les termes, la somme ne change pas.",
"Ноль и единица": "Zéro et un",
"Теперь про прибавление нуля и единицы.": "Voyons maintenant l'ajout de zéro et de un.",
"Видео: Таблица сложения": "Vidéo : la table d'addition",
"Волшебная таблица": "Le tableau magique",
"Это таблица сложения. Строка — первое слагаемое, столбец — второе, а в клетке — сумма. Нажимай на клетки и смотри, что подсвечивается.": "Voici la table d'addition. La ligne est le premier terme, la colonne le second, et dans la case se trouve la somme. Clique sur les cases et regarde ce qui s'illumine.",
"Охота за суммой": "Chasse à la somme",
"Задание: найди в таблице все клетки с загаданным числом. Какую картинку они образуют? Подсказка: ищи их на одной косой линии.": "Consigne : trouve dans le tableau toutes les cases avec le nombre choisi. Quelle image forment-elles ? Indice : cherche-les sur une même ligne oblique.",
"Быстрые примеры": "Exemples rapides",
"Решай примеры. Таблица тебе поможет, но лучше вспомнить ответ самостоятельно!": "Résous les exemples. Le tableau t'aidera, mais c'est mieux de retrouver la réponse tout seul !",
"Теперь ты знаешь, что такое сложение, умеешь прыгать по числовому лучу, раскладывать числа на части, помнишь свойства и таблицу. Дальше — тренировка без конца!": "Maintenant, tu sais ce qu'est l'addition, tu sais sauter sur la droite numérique, décomposer les nombres, et tu te souviens des propriétés et de la table. Ensuite : entraînement sans fin !",
