"Сложи монеты в каждом варианте. Нужно получить": "Additionne les pièces dans chaque option. Il faut obtenir",
"Это самая маленькая монета.": "C'est la plus petite pièce.",
"Из этих монет 20 тенге — самая дорогая. Это два десятка.": "Parmi ces pièces, 20 tenge est la plus chère. C'est deux dizaines.",
"10 тенге — это один десяток.": "10 tenge, c'est une dizaine.",
"Чем больше число на монете, тем она дороже.": "Plus le nombre sur la pièce est grand, plus elle vaut cher.",
"Деньги Казахстана называются тенге.": "L'argent du Kazakhstan s'appelle le tenge.",
