"тг. Добавь монеты.": "tg. Ajoute des pièces.",
"Выложено на": "Tu as posé",
"тг больше, чем нужно. Нажми «Убрать монеты» и попробуй ещё.": "tg de plus que nécessaire. Clique sur « Retirer les pièces » et réessaie.",
"Видео: Монеты Казахстана": "Vidéo : les pièces du Kazakhstan",
"Знакомимся с монетами": "Faisons connaissance avec les pièces",
"Привет! Это Барсик. В Казахстане платят тенге. Есть монеты в 1, 2, 5, 10 и 20 тенге. Нажимай на каждую монету и смотри.": "Salut ! C'est Barsik. Au Kazakhstan, on paie en tenge. Il y a des pièces de 1, 2, 5, 10 et 20 tenge. Clique sur chaque pièce et regarde.",
"Какая дороже?": "Laquelle vaut le plus ?",
"Чем больше число на монете, тем монета дороже. Сравни числа и выбери нужную монету.": "Plus le nombre sur la pièce est grand, plus la pièce vaut cher. Compare les nombres et choisis la bonne pièce.",
"Видео: Сколько денег?": "Vidéo : combien d'argent ?",
"Считаем монеты": "Comptons les pièces",
"Чтобы узнать, сколько всего денег, сложи числа на монетах. Начни с самых больших монет.": "Pour savoir combien d'argent il y a en tout, additionne les nombres sur les pièces. Commence par les plus grandes pièces.",
"Разменяем монету": "Changeons une pièce",
"Монета в 20 тенге — это два десятка. Её можно разменять на монеты поменьше. Сколько денег получится, всегда должно сойтись.": "La pièce de 20 tenge, c'est deux dizaines. On peut la changer en pièces plus petites. La somme doit toujours rester la même.",
"Видео: Покупаем": "Vidéo : on achète",
"Заплати ровно": "Paie la somme exacte",
"В магазине у каждой вещи есть цена. Выбирай монеты из кошелька так, чтобы вышла ровно цена, и нажимай «Заплатить».": "Dans le magasin, chaque chose a un prix. Choisis dans le porte-monnaie des pièces pour obtenir exactement le prix, puis clique sur « Payer ».",
"Чем заплатить?": "Avec quoi payer ?",
"Сложи числа на монетах в каждом варианте. Нужен тот вариант, где получается ровно цена.": "Additionne les nombres sur les pièces dans chaque option. Il faut celle qui donne exactement le prix.",
"Две покупки": "Deux achats",
"Если покупаешь две вещи, цены складывают. Узнай, сколько всего нужно заплатить.": "Si tu achètes deux choses, on additionne les prix. Trouve combien il faut payer en tout.",
"Видео: Хватит ли денег? Сдача": "Vidéo : y a-t-il assez d'argent ? La monnaie",
"Хватит ли денег?": "Y a-t-il assez d'argent ?",
"Сравни, сколько денег есть и сколько стоит вещь. Если денег не меньше, чем цена, то хватит.": "Compare l'argent que tu as et le prix de l'objet. Si l'argent n'est pas inférieur au prix, il y en a assez.",
"Сдача": "La monnaie",
"Если заплатить больше, чем стоит покупка, продавец вернёт сдачу. Чтобы найти сдачу, вычти цену из заплаченных денег.": "Si tu paies plus que le prix, le vendeur rend la monnaie. Pour trouver la monnaie, soustrais le prix de l'argent payé.",
"Последняя проверка курса: монеты, счёт денег, покупки и сдача.": "Dernière vérification du cours : pièces, compter l'argent, achats et monnaie.",
"Теперь ты знаешь наши монеты, умеешь считать деньги, платить за покупки и находить сдачу. Дальше — тренировка без конца в игре. Я буду рядом!": "Maintenant tu connais nos pièces, tu sais compter l'argent, payer tes achats et trouver la monnaie. Ensuite : entraînement sans fin dans le jeu. Je serai là !",
