"Синие": "Bleus",
"Красные в одной коробке, синие — в другой. Это разложили по цвету.": "Les rouges sont dans une boîte, les bleus dans l'autre. On les a rangés par couleur.",
"Посмотри на цвет фигуры: красные идут к красным, синие — к синим.": "Regarde la couleur de la figure : les rouges vont avec les rouges, les bleues avec les bleues.",
