"Круги в одной коробке, квадраты — в другой. Это разложили по форме.": "Les cercles sont dans une boîte, les carrés dans l'autre. On les a rangés par forme.",
"Цвет не важен. Смотри на форму фигуры: круг или квадрат.": "La couleur n'a pas d'importance. Regarde la forme de la figure : cercle ou carré.",
