", а сейчас": ", mais il y a maintenant",
". Поправь значки.": ". Corrige les icônes.",
"Видео: Верно или неверно": "Vidéo : vrai ou faux",
"Проверяем по картинке": "Vérifions avec l'image",
"Привет! Это Барсик. Утверждение — это предложение, про которое можно сказать: верно оно или неверно. Посчитай фигуры на картинке и проверь, правду ли говорит утверждение.": "Salut ! C'est Barsik. Une affirmation est une phrase dont on peut dire si elle est vraie ou fausse. Compte les figures sur l'image et vérifie si l'affirmation dit vrai.",
"Проверяем числа": "Vérifions les nombres",
"Проверь запись с числами: правильно ли поставлен знак или посчитана сумма. Правильная запись — верная, неправильная — неверная.": "Vérifie l'écriture avec des nombres : le signe est-il bien placé, la somme bien calculée. Une écriture correcte est vraie, une écriture incorrecte est fausse.",
"Проверяем про фигуры": "Vérifions les affirmations sur les figures",
"Теперь утверждения про фигуры. Вспомни, сколько у них сторон и какие они бывают, и скажи, верно ли утверждение.": "Maintenant, des affirmations sur les figures. Rappelle-toi combien elles ont de côtés et quelles sortes il existe, et dis si l'affirmation est vraie.",
"Видео: Признаки и лишнее": "Vidéo : caractéristiques et intrus",
"Раскладываем фигуры": "Trions les figures",
"У предметов бывают признаки: цвет, форма, размер. По признаку можно разложить предметы на группы. Нажми на фигуру, а потом на коробку, куда она подходит.": "Les objets ont des caractéristiques : couleur, forme, taille. On peut trier les objets en groupes selon une caractéristique. Clique sur la figure, puis sur la boîte qui lui convient.",
"Сколько с таким признаком?": "Combien ont cette caractéristique ?",
"Считай только те фигуры, у которых есть нужный признак: нужный цвет или нужная форма.": "Compte seulement les figures qui ont la caractéristique voulue : la bonne couleur ou la bonne forme.",
"Что лишнее?": "Quel est l'intrus ?",
"Лишний предмет — тот, который не похож на остальные. Найди, чем он отличается: цветом или формой.": "L'intrus est l'objet qui ne ressemble pas aux autres. Trouve en quoi il diffère : couleur ou forme.",
"Видео: Пиктограммы": "Vidéo : les pictogrammes",
"Рисуем пиктограмму": "Dessinons un pictogramme",
"Пиктограмма — это картинка с данными: один значок значит один предмет. Так удобно считать и сравнивать. Нарисуй пиктограмму по рассказу Барсика.": "Un pictogramme est une image avec des données : une icône représente un objet. C'est pratique pour compter et comparer. Dessine un pictogramme d'après le récit de Barsik.",
"Читаем пиктограмму": "Lisons un pictogramme",
"Смотри на длину строки: чем больше значков, тем больше предметов. Отвечай на вопросы по пиктограмме.": "Regarde la longueur de la ligne : plus il y a d'icônes, plus il y a d'objets. Réponds aux questions d'après le pictogramme.",
"Видео: Ребусы и логические задачи": "Vidéo : rébus et problèmes de logique",
"Ребусы с картинками": "Rébus en images",
"В ребусе одинаковые картинки значат одинаковые числа. Подбери число, чтобы запись стала верной.": "Dans un rébus, les mêmes images représentent les mêmes nombres. Choisis un nombre pour que l'écriture soit vraie.",
"Кто выше?": "Qui est le plus grand ?",
"Выстрой героев по порядку и найди самого высокого или самого низкого. Рассуждай по шагам.": "Range les personnages dans l'ordre et trouve le plus grand ou le plus petit. Raisonne pas à pas.",
"Какого цвета шарик?": "De quelle couleur est le ballon ?",
"Исключай то, что не подходит. Что останется, то и будет ответом.": "Élimine ce qui ne convient pas. Ce qui reste est la réponse.",
"Видео: Комбинации": "Vidéo : les combinaisons",
"Составляем наряды": "Composons des tenues",
"Комбинация — это сочетание двух предметов, например, футболки и шапки. Составь все возможные пары и не пропусти ни одной.": "Une combinaison est l'association de deux objets, par exemple un T-shirt et un chapeau. Forme toutes les paires possibles et n'en oublie aucune.",
"Сколько вариантов?": "Combien de possibilités ?",
"Чтобы не запутаться, составляй пары по порядку: с первым предметом, потом со вторым и так далее.": "Pour ne pas t'embrouiller, forme les paires dans l'ordre : avec le premier objet, puis avec le deuxième, et ainsi de suite.",
"Последняя проверка курса: верно или неверно, признаки, пиктограммы, ребусы, логика и комбинации.": "Dernière vérification du cours : vrai ou faux, caractéristiques, pictogrammes, rébus, logique et combinaisons.",
"Теперь ты умеешь проверять утверждения, раскладывать предметы по признакам, читать пиктограммы, решать ребусы и составлять комбинации. Дальше — тренировка без конца в игре. Я буду рядом!": "Maintenant tu sais vérifier des affirmations, trier des objets selon leurs caractéristiques, lire des pictogrammes, résoudre des rébus et former des combinaisons. Ensuite : entraînement sans fin dans le jeu. Je serai là !",
