"Видео: Сантиметр": "Vidéo : le centimètre",
"Линейка и сантиметры": "La règle et les centimètres",
"Привет! Это Барсик. Длину измеряют линейкой. Карандаш кладут началом на ноль, а число у его конца показывает длину в сантиметрах. Нажимай на числа и смотри.": "Salut ! C'est Barsik. On mesure la longueur avec une règle. On place le début du crayon sur zéro, et le nombre au bout du crayon donne la longueur en centimètres. Clique sur les nombres et regarde.",
"Измерь сам": "Mesure toi-même",
"Теперь твоя очередь. Найди, у какого числа заканчивается карандаш, и нажми на это число.": "C'est maintenant ton tour. Trouve à quel nombre le crayon se termine et clique sur ce nombre.",
"Начерти отрезок": "Trace un segment",
"Линейкой можно не только измерять, но и чертить. Чтобы начертить отрезок нужной длины, начни с нуля и закончи у нужного числа.": "La règle sert non seulement à mesurer, mais aussi à tracer. Pour tracer un segment de la longueur voulue, commence à zéro et termine au nombre voulu.",
"Какова длина?": "Quelle est la longueur ?",
"Посмотри, где заканчивается карандаш, и выбери его длину в сантиметрах.": "Regarde où le crayon se termine et choisis sa longueur en centimètres.",
"Длиннее и короче": "Plus long et plus court",
"Сравни два карандаша: чем дальше от нуля заканчивается карандаш, тем он длиннее.": "Compare deux crayons : plus le crayon se termine loin de zéro, plus il est long.",
"Видео: Дециметр": "Vidéo : le décimètre",
"Десять сантиметров": "Dix centimètres",
"Когда сантиметров набирается десять, получается новая единица — дециметр. Нажимай кнопки и смотри, как сантиметры собираются в дециметры.": "Quand on a dix centimètres, on obtient une nouvelle unité : le décimètre. Clique sur les boutons et regarde comment les centimètres se rassemblent en décimètres.",
"Дециметры и сантиметры": "Décimètres et centimètres",
"Помни: один дециметр — это десять сантиметров. Переведи одни единицы в другие.": "Souviens-toi : un décimètre, c'est dix centimètres. Convertis une unité dans l'autre.",
"На сколько длиннее?": "De combien est-il plus long ?",
"Чтобы узнать, на сколько один карандаш длиннее другого, вычти меньшую длину из большей.": "Pour savoir de combien un crayon est plus long qu'un autre, soustrais la plus petite longueur de la plus grande.",
"Видео: Килограмм": "Vidéo : le kilogramme",
"Взвешиваем на весах": "Pesons sur la balance",
"Массу измеряют весами в килограммах. На одну чашу кладут товар, на другую — гири. Когда весы ровные, масса товара равна массе гирь. Добавляй гири по 1 килограмму.": "On mesure la masse avec une balance, en kilogrammes. On met la marchandise sur un plateau et des poids sur l'autre. Quand la balance est équilibrée, la masse de la marchandise est égale à celle des poids. Ajoute des poids de 1 kilogramme.",
"Что тяжелее?": "Qu'est-ce qui est plus lourd ?",
"У тяжёлого предмета масса больше, у лёгкого — меньше. Выбери нужный предмет.": "Un objet lourd a une plus grande masse, un objet léger a une plus petite masse. Choisis l'objet voulu.",
"Задачи про килограммы": "Problèmes sur les kilogrammes",
"Килограммы складывают и вычитают так же, как обычные числа. Не забывай про единицу измерения в ответе.": "On additionne et on soustrait les kilogrammes comme des nombres ordinaires. N'oublie pas l'unité de mesure dans la réponse.",
"Видео: Литр": "Vidéo : le litre",
"Наливаем литры": "Versons des litres",
"Сколько жидкости помещается в сосуд, измеряют в литрах. Нажимай кнопку, чтобы налить воду литр за литром, и остановись на нужном числе.": "Ce que peut contenir un récipient se mesure en litres. Clique sur le bouton pour verser l'eau litre par litre et arrête-toi au nombre voulu.",
"Задачи про литры": "Problèmes sur les litres",
"Литры складывают и вычитают так же, как килограммы и сантиметры. Прочитай задачу и выбери ответ.": "On additionne et on soustrait les litres comme les kilogrammes et les centimètres. Lis le problème et choisis la réponse.",
"Видео: Чем и в чём измерять": "Vidéo : avec quoi et dans quoi mesurer",
"Чем измерить?": "Avec quoi mesurer ?",
"Длину измеряют линейкой, массу — весами, а сколько жидкости — литровой банкой. Выбери подходящий прибор.": "On mesure la longueur avec une règle, la masse avec une balance, et la quantité de liquide avec un bocal d'un litre. Choisis l'instrument qui convient.",
"В каких единицах?": "Dans quelles unités ?",
"Длину — в сантиметрах, массу — в килограммах, жидкость — в литрах. Выбери верную единицу.": "La longueur en centimètres, la masse en kilogrammes, le liquide en litres. Choisis la bonne unité.",
"Последняя проверка курса: длина, масса и литры.": "Dernière vérification du cours : longueur, masse et litres.",
"Теперь ты умеешь измерять длину в сантиметрах и дециметрах, знаешь килограмм и литр и можешь решать задачи про них. Дальше — тренировка без конца в игре. Я буду рядом!": "Maintenant tu sais mesurer la longueur en centimètres et en décimètres, tu connais le kilogramme et le litre et tu peux résoudre des problèmes à leur sujet. Ensuite : entraînement sans fin dans le jeu. Je serai là !",
