"Правее": "Plus à droite",
"Левее": "Plus à gauche",
"На числовом луче числа растут слева направо.": "Sur la droite numérique, les nombres augmentent de gauche à droite.",
"Правее стоит большее число": "À droite se trouve le plus grand nombre",
"Левее стоит меньшее число": "À gauche se trouve le plus petit nombre",
"Между": "Entre",
"слева никого нет, он с краю": "à gauche, il n'y a personne, il est au bord",
"справа никого нет, он с краю": "à droite, il n'y a personne, il est au bord",
