"Он стоит посередине.": "Il est au milieu.",
"Слева, справа и между: теперь ты знаешь, как найти место предмета.": "À gauche, à droite et entre : maintenant tu sais comment trouver la place d'un objet.",
"из 4 нужных.": "sur 4 nécessaires.",
"на столе": "sur la table",
"под столом": "sous la table",
"над столом": "au-dessus de la table",
"рядом со столом": "à côté de la table",
"вне коробки": "en dehors de la boîte",
"Теперь ты знаешь, как сказать, где находится предмет.": "Maintenant tu sais comment dire où se trouve un objet.",
"Показано положений:": "Positions vues :",
"из 5 нужных.": "sur 5 nécessaires.",
"Видео: Слева, справа, впереди, между": "Vidéo : à gauche, à droite, devant, entre",
"Кто где стоит": "Qui se tient où",
"Привет! Это Барсик. Чтобы сказать, где находится предмет, используют слова: слева, справа, между, с краю, посередине. Нажимай на животных!": "Salut ! C'est Barsik. Pour dire où se trouve un objet, on utilise ces mots : à gauche, à droite, entre, au bord, au milieu. Clique sur les animaux !",
"Слева или справа?": "À gauche ou à droite ?",
"Найди животное на картинке и посмотри на соседей. Слева — там, где левая рука, справа — где правая.": "Trouve cet animal sur l'image et regarde ses voisins. La gauche est du côté de la main gauche, la droite du côté de la main droite.",
"Впереди и позади": "Devant et derrière",
"Когда все идут в одну сторону, впереди — тот, кто идёт первым, а позади — тот, кто идёт следом.": "Quand tous vont dans la même direction, devant, c'est celui qui marche en premier, et derrière, celui qui suit.",
"Между, с краю, посередине": "Entre, au bord, au milieu",
"Между — это в середине двух предметов. С краю — самый первый или самый последний. Посередине — одинаково далеко от обоих краёв.": "Entre, c'est au milieu de deux objets. Au bord, c'est tout le premier ou tout le dernier. Au milieu, c'est à égale distance des deux bords.",
"Видео: Выше, ниже, над, под": "Vidéo : plus haut, plus bas, au-dessus, en dessous",
"Где мячик": "Où est le ballon",
"Нажимай на кнопки, и мячик будет перемещаться. Смотри внимательно: на столе, под столом, над столом, рядом, в коробке, вне коробки.": "Clique sur les boutons, et le ballon se déplacera. Regarde bien : sur la table, sous la table, au-dessus de la table, à côté, dans la boîte, en dehors de la boîte.",
"На, под, над, рядом": "Sur, sous, au-dessus, à côté",
"Посмотри, где находится мячик по отношению к столу, и выбери нужное слово.": "Regarde où se trouve le ballon par rapport à la table et choisis le mot voulu.",
"Выше и ниже": "Plus haut et plus bas",
"В этом доме живут звери. Чем выше этаж, тем ближе он к крыше. Найди, кто живёт выше или ниже.": "Dans cette maison vivent des animaux. Plus l'étage est haut, plus il est près du toit. Trouve qui habite plus haut ou plus bas.",
"Видео: Внутри, снаружи, посередине": "Vidéo : dedans, dehors, au milieu",
"Внутри или снаружи?": "Dedans ou dehors ?",
"Если предмет окружён со всех сторон, он внутри. Если он за границей, он вне, то есть снаружи.": "Si un objet est entouré de tous les côtés, il est dedans. S'il est au-delà de la limite, il est dehors, c'est-à-dire à l'extérieur.",
"Слева, посередине, справа": "Gauche, milieu, droite",
"Три кружка стоят в ряд. Назови цвет того, который слева, посередине или справа.": "Trois ronds sont alignés. Dis la couleur de celui qui est à gauche, au milieu ou à droite.",
"Видео: Сравниваем предметы": "Vidéo : comparons des objets",
"Что больше, выше, шире, толще?": "Qu'est-ce qui est plus grand, plus haut, plus large, plus épais ?",
"Посмотри на два предмета и сравни их. Больше — меньше, выше — ниже, шире — уже, толще — тоньше.": "Regarde deux objets et compare-les. Grand, petit ; haut, bas ; large, étroit ; épais, mince.",
"Сравни в жизни": "Compare dans la vie",
"Подумай о настоящих предметах. Жираф выше кошки, а ручей уже реки.": "Pense à de vrais objets. La girafe est plus haute que le chat, et le ruisseau est plus étroit que la rivière.",
"Видео: Ближе, дальше, числовой луч": "Vidéo : plus près, plus loin, la droite numérique",
"Ближе или дальше?": "Plus près ou plus loin ?",
"Расстояние — это путь от одного места до другого. Что ближе к школе, до того путь короче.": "La distance est le chemin d'un endroit à un autre. Ce qui est plus près de l'école a un chemin plus court.",
"Слева и справа на луче": "La gauche et la droite sur la droite numérique",
"На числовом луче числа растут слева направо. Чем правее число, тем оно больше.": "Sur la droite numérique, les nombres augmentent de gauche à droite. Plus un nombre est à droite, plus il est grand.",
"Последняя проверка курса: слева и справа, выше и ниже, внутри и снаружи, сравнение и числовой луч.": "Dernière vérification du cours : gauche et droite, plus haut et plus bas, dedans et dehors, comparaison et droite numérique.",
"Теперь ты можешь рассказать, где находится предмет, и сравнить предметы по размеру. Дальше — тренировка без конца в игре. Я буду рядом!": "Maintenant tu peux dire où se trouve un objet et comparer des objets par leur taille. Ensuite : entraînement sans fin dans le jeu. Je serai là !",
