"Условие": "Condition",
"Это вопрос: в нём спрашивают, что нужно найти, и он заканчивается знаком «?».": "C'est la question : on y demande ce qu'il faut trouver, et elle se termine par « ? ».",
"Это условие: в нём сказано, что известно. Искать здесь ничего не нужно.": "C'est la condition : elle dit ce qui est connu. Il n'y a rien à chercher ici.",
"больше, чем у": "plus que",
