"стало?": "y en a-t-il maintenant ?",
"Сейчас в корзине": "Maintenant, dans le panier, il y a",
". Недавно положили": ". On vient de mettre",
"лежало сначала?": "y en avait-il au début ?",
". Сначала лежало": ". Au début, il y en avait",
"положили?": "en a-t-on mis ?",
"в корзине?": "y en a-t-il dans le panier ?",
"В обратной задаче известен ответ прямой задачи (": "Dans le problème inverse, on connaît la réponse du problème direct (",
"), а искать нужно то, что раньше было известно. Такая задача: «": "), et il faut chercher ce qui était connu avant. Un tel problème est : «",
"Нажми на предложение, которое является вопросом задачи.": "Clique sur la phrase qui est la question du problème.",
"Вопрос — это то, что нужно найти. Остальное — условие: то, что известно.": "La question, c'est ce qu'il faut trouver. Le reste est la condition : ce qui est connu.",
"Это не вопрос. Вопрос заканчивается знаком «?» и спрашивает, что нужно найти.": "Ce n'est pas une question. Une question se termine par « ? » et demande ce qu'il faut trouver.",
"Добавили": "On a ajouté",
"Стало": "Il y a maintenant",
"Отдали": "On a donné",
"Осталось": "Il reste",
"Краткая запись и схема помогают понять задачу и выбрать действие.": "Une écriture courte et un schéma aident à comprendre le problème et à choisir l'opération.",
"первого": "du premier",
"второго": "du deuxième",
"Лишние предметы показывают, на сколько одно число больше другого.": "Les objets en trop montrent de combien un nombre est plus grand qu'un autre.",
"Пример": "Exemple",
"Неизвестное слагаемое находим вычитанием:": "On trouve le terme inconnu par soustraction :",
"Неизвестное вычитаемое:": "Le terme soustrait inconnu :",
"Сейчас слева получается": "Maintenant, à gauche, on obtient",
", а должно быть": ", mais il doit y avoir",
". Попробуй другое число.": ". Essaie un autre nombre.",
"Видео: Из чего состоит задача": "Vidéo : de quoi se compose un problème",
"Найди вопрос задачи": "Trouve la question du problème",
"Привет! Это Барсик. В задаче есть условие, где сказано, что известно, и вопрос, где сказано, что нужно найти. Вопрос заканчивается знаком вопроса. Нажми на предложение, которое является вопросом.": "Salut ! C'est Barsik. Dans un problème, il y a la condition, où l'on dit ce qui est connu, et la question, où l'on dit ce qu'il faut trouver. La question se termine par un point d'interrogation. Clique sur la phrase qui est la question.",
"Условие или вопрос": "Condition ou question",
"Прочитай предложение и скажи, что это: условие или вопрос. В вопросе спрашивают, а в условии рассказывают, что известно.": "Lis la phrase et dis ce que c'est : une condition ou une question. La question demande, la condition raconte ce qui est connu.",
"Видео: Сумма и остаток": "Vidéo : somme et reste",
"Краткая запись и схема": "Écriture courte et schéma",
"Чтобы понять задачу, её можно записать коротко и нарисовать схему. Выбирай сумму или остаток, нажимай кнопку и смотри, как строится схема и как находится ответ.": "Pour comprendre un problème, on peut l'écrire brièvement et dessiner un schéma. Choisis la somme ou le reste, clique sur le bouton et regarde comment le schéma se construit et comment on trouve la réponse.",
"Находим сумму": "Trouver la somme",
"В этих задачах предметов становится больше или нужно узнать, сколько их вместе. Складывай.": "Dans ces problèmes, il y a plus d'objets ou il faut savoir combien il y en a en tout. Additionne.",
"Находим остаток": "Trouver le reste",
"В этих задачах часть предметов убрали или отдали. Вычти, чтобы узнать, сколько осталось.": "Dans ces problèmes, une partie des objets a été retirée ou donnée. Soustrais pour savoir combien il en reste.",
"Какое действие выбрать": "Quelle opération choisir",
"Прочитай задачу и выбери действие. Если предметов стало больше или нужно узнать, сколько вместе, то складываем. Если убрали, то вычитаем.": "Lis le problème et choisis l'opération. S'il y a plus d'objets ou s'il faut savoir combien il y en a en tout, on additionne. Si on en a retiré, on soustrait.",
"Видео: Больше и меньше": "Vidéo : plus et moins",
"На сколько больше": "De combien en plus",
"Меняй числа кнопками и смотри на предметы. Лишние предметы показывают, на сколько одно число больше другого. Чтобы это узнать, из большего числа вычитают меньшее.": "Change les nombres avec les boutons et regarde les objets. Les objets en trop montrent de combien un nombre est plus grand qu'un autre. Pour le savoir, soustrais le plus petit nombre du plus grand.",
"На несколько больше или меньше": "Quelques-uns de plus ou de moins",
"В этих задачах сказано, на сколько у одного больше или меньше, чем у другого. Если больше, то прибавляем. Если меньше, то вычитаем.": "Dans ces problèmes, on dit de combien l'un en a plus ou moins que l'autre. Si c'est plus, on additionne. Si c'est moins, on soustrait.",
"На сколько больше или меньше": "De combien en plus ou en moins",
"Теперь нужно узнать, на сколько одно число больше или меньше другого. Вычти из большего меньшее.": "Maintenant, il faut savoir de combien un nombre est plus grand ou plus petit qu'un autre. Soustrais le plus petit du plus grand.",
"Видео: Неизвестное число": "Vidéo : le nombre inconnu",
"Число в квадрате": "Le nombre dans le carré",
